declare(strict_types=1);require_once __DIR__.'/auth.php';if(current_user())redirect('panel.php');$error='';$return=(string)($_GET['return']??$_POST['return']??'panel.php');$legacyPath=(string)(parse_url($return,PHP_URL_PATH)??'');$legacyQuery=[];parse_str((string)(parse_url($return,PHP_URL_QUERY)??''),$legacyQuery);if(in_array(ltrim($legacyPath,'/'),['historial.php'],true)&&preg_match('/^[A-Za-z0-9_-]{1,80}$/',(string)($legacyQuery['carro']??'')))redirect('ver.php?carro='.rawurlencode((string)$legacyQuery['carro']));if($_SERVER['REQUEST_METHOD']==='POST'){$correo=strtolower(trim((string)($_POST['correo']??'')));$password=(string)($_POST['password']??'');$stmt=db()->prepare('SELECT id,nombre,correo,password_hash,rol FROM usuarios WHERE correo=? AND activo=1 LIMIT 1');$stmt->execute([$correo]);$account=$stmt->fetch();if($account&&password_verify($password,$account['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$account['id'];redirect((str_starts_with($return,'/')&&!str_starts_with($return,'//'))?$return:'panel.php');}$error='Correo o contraseña incorrectos.';}
